const KEY_EVO = 'f7aaaba7593506765800c7d58133007a';
const INSTANCE = 'secretaria-clinica';
const OKEY = '<REDACTED_OPENAI_KEY>';
const OMODEL = 'gpt-4o-mini';
const GKEY = '<REDACTED_GOOGLE_KEY>';
const MODEL = 'gemini-2.5-flash-lite';
const MODEL_FALLBACK = 'gemini-2.5-flash';
const ALERT_GROUP = \u<REDACTED_WA_GROUP_JID>';
const https = require('https');
const sleep = (ms)=> new Promise(r=>setTimeout(r,ms));

const root = $input.first().json;
const body = root.body || root;
const event = body.event || '';
const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const fromMe = key.fromMe === true;
const pushName = data.pushName || '';

function skip(reason){ return [{ json: { ok:true, skipped:reason } }]; }
if (event && event !== 'messages.upsert') return skip('event:'+event);
if (!remoteJid) return skip('no-jid');

const msg = data.message || {};
const text = (msg.conversation
  || (msg.extendedTextMessage && msg.extendedTextMessage.text)
  || (msg.imageMessage && msg.imageMessage.caption)
  || '').trim();

const s = $getWorkflowStaticData('global');
s.conv = s.conv || {};
s.paused = s.paused || {};
s.appts = s.appts || [];
const PAUSE_MS = 6*3600000;

function waSend(target, txt, delayMs){
  return new Promise((resolve)=>{
    const obj = { number: target, text: txt };
    // delay/presence NAO vai no body do Evolution (quebrava entrega - ficava so digitando)
    const payload = JSON.stringify(obj);
    const req = https.request({
      hostname:\<REDACTED_PRIVATE_HOST>',
      path:'/message/sendText/'+INSTANCE,
      method:'POST',
      headers:{'Content-Type':'application/json','apikey':KEY_EVO,'Content-Length':Buffer.byteLength(payload)}
    }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve({code:res.statusCode,body:d.slice(0,160)})); });
    req.on('error',(e)=>resolve({code:0,err:e.message}));
    req.setTimeout(30000,()=>{ req.destroy(); resolve({code:0,err:'timeout'}); });
    req.write(payload); req.end();
  });
}

function parseDT(dia, hora){
  const dm = (dia||'').match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (!dm) return null;
  let d=dm[1], mo=dm[2], y=dm[3]; if (y.length===2) y='20'+y;
  const hm = (hora||'').match(/(\d{1,2})(?:[:h](\d{2}))?/);
  let hh = hm ? parseInt(hm[1],10) : 9; let mm = (hm && hm[2]) ? parseInt(hm[2],10) : 0;
  return Date.UTC(parseInt(y,10), parseInt(mo,10)-1, parseInt(d,10), hh+3, mm, 0);
}

if (remoteJid === ALERT_GROUP) {
  const low = text.toLowerCase();
  if (low.startsWith('voltar') || low.startsWith('liberar')) {
    if (low.includes('todos')) {
      s.paused = {};
      await waSend(ALERT_GROUP, '✅ Bot reativado para TODOS os contatos.');
      return [{ json:{ ok:true, action:'resume-all' } }];
    }
    const digits = (text.match(/\d{8,15}/) || [])[0];
    if (digits) {
      const jid = digits + \<REDACTED_EMAIL>';
      delete s.paused[jid];
      await waSend(ALERT_GROUP, '✅ Bot reativado para +' + digits + '. Volta a responder esse paciente.');
      return [{ json:{ ok:true, action:'resume', jid } }];
    }
    await waSend(ALERT_GROUP, 'Uso: "voltar <REDACTED_PHONE_BR>" (numero do paciente) ou "voltar todos".');
    return [{ json:{ ok:true, action:'resume-help' } }];
  }
  return skip('group-msg');
}

if (fromMe) return skip('fromMe');
if (remoteJid.endsWith(\<REDACTED_EMAIL>') || remoteJid === 'status@broadcast') return skip('jid:'+remoteJid);
if (!text) return skip('no-text');

const number = remoteJid.split('@')[0];

if (text.toUpperCase() === 'RESETBOT') {
  delete s.paused[remoteJid];
  s.conv[remoteJid] = [];
  s.appts = (s.appts||[]).filter(a=>a.number!==number);
  await waSend(remoteJid, 'Pronto! Pode testar de novo. 👍');
  return [{ json:{ ok:true, action:'reset', number } }];
}

s.conv[remoteJid] = s.conv[remoteJid] || [];
const hist = s.conv[remoteJid];
if (s.paused[remoteJid] && (Date.now() - s.paused[remoteJid] < PAUSE_MS)) return skip('handoff-paused');

const _n = new Date();
const diaSemana = _n.toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long'});
const dataHoje = _n.toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'});
const horaAgora = _n.toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'});

const SYSTEM = [
 'Voce e a secretaria virtual da Clinica Sorriso (odontologia), atendendo pacientes no WhatsApp.',
 'HOJE e ' + diaSemana + ', ' + dataHoje + ', e agora sao ' + horaAgora + ' (horario de Brasilia). Use isso para calcular QUALQUER data relativa. SEMPRE escreva a data confirmada no formato DD/MM/AAAA. NUNCA marque data no passado; se a referencia ja passou, use a proxima ocorrencia futura.',
 'Objetivo: agendar, reagendar, cancelar, confirmar horarios, tirar duvidas de valores, convenios, endereco e horario de funcionamento, e reativar pacientes que sumiram.',
 'Estilo: simpatica, calorosa e OBJETIVA. Respostas curtas (e WhatsApp), no maximo 3 linhas. Use no maximo 1 emoji. Nunca repita informacao que ja disse. NUNCA escreva a palavra "marcadores" nem mostre ou explique os codigos entre colchetes ao paciente — eles sao apenas internos do sistema, o paciente jamais deve ve-los.',
 'Regras: nunca invente preco ou informacao que nao tem. Como ainda NAO ha agenda integrada, considere QUALQUER horario dentro do funcionamento como DISPONIVEL — nunca diga que um horario esta ocupado, cheio, reservado ou em almoco; so recuse horarios FORA do funcionamento. Sempre conduza pro proximo passo. Antes de fechar, tente saber o NOME do paciente e o MOTIVO/servico. Confira sempre se a data e futura e dentro do funcionamento antes de confirmar.',
 'Se o paciente so puder em horario fora do funcionamento, seja honesta: diga que nao atende nesse horario, ofereca o mais proximo e pergunte qual dia prefere. Nao repita a tabela de horarios.',
 'Se o paciente responder confirmando presenca a um lembrete (ex: SIM, confirmado), agradeca de forma curta e NAO gere marcador.',
 'MARCADORES (SEMPRE no FINAL, formato exato, so quando dia E horario confirmados). Data DEVE ser DD/MM/AAAA:',
 '- Novo: [AGENDAMENTO|nome|servico|DD/MM/AAAA|horario|observacao]',
 '- Remarcar: [REAGENDAMENTO|nome|servico|DD/MM/AAAA|horario|observacao]',
 '- Cancelar: [CANCELAMENTO|nome|motivo]',
 'Observacao = detalhe relevante (atraso, preferencia, alergia, convenio). Se nao houver, use hifen (-). Se nao souber o nome use Paciente.',
 'ENCAMINHAR PRA RECEPCAO (handoff) — use com MUITA PARCIMONIA, so em casos CLAROS: reclamacao seria, urgencia ou dor forte de verdade, ou o paciente PEDIR explicitamente pra falar com um humano/recepcao/atendente. NAO encaminhe por duvida comum, agendamento, preco, convenio, horario ou qualquer coisa que voce consiga responder — nesses casos responda voce mesma normalmente. Na duvida, NAO encaminhe. So quando for realmente necessario: responda 1 frase curta avisando e coloque no FINAL o marcador exato [HANDOFF].',
 'Dados ficticios p/ teste: Seg-Sex 8h-20h, Sab 9h-13h. Endereco: Rua Exemplo, 123 - Sorocaba. Avaliacao inicial: gratuita. NAO existe pausa de almoco: 12h, 13h, 14h e qualquer horario entre 8h e 20h atendem normalmente. Se o paciente pedir um horario nesse intervalo, CONFIRME — nunca recuse por almoco ou por achar que esta ocupado.'
].join('\n');

let sliced = hist.slice(-10);
while (sliced.length && sliced[0].role !== 'user') sliced.shift();
const contents = [];
for (const h of sliced) contents.push({ role: h.role, parts:[{text:h.text}] });
contents.push({ role:'user', parts:[{text}] });
const omsgs=[{role:'system',content:SYSTEM}];
for (const h of sliced) omsgs.push({ role: h.role==='model'?'assistant':h.role, content:h.text });
omsgs.push({ role:'user', content:text });

function callModelOnce(model){
  return new Promise((resolve)=>{
    const payload = JSON.stringify({
      systemInstruction: { parts:[{text:SYSTEM}] },
      contents,
      generationConfig: { temperature:0.6, maxOutputTokens:500, thinkingConfig:{ thinkingBudget:0 } }
    });
    const req = https.request({
      hostname:'generativelanguage.googleapis.com',
      path:'/v1beta/models/'+model+':generateContent?key='+GKEY,
      method:'POST',
      headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(payload)}
    }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>{ try{ const j=JSON.parse(d); const p=(((j.candidates||[])[0]||{}).content||{}).parts; const t=(p&&p[0]&&p[0].text)?p[0].text.trim():''; resolve({status:res.statusCode, text:t}); }catch(e){ resolve({status:res.statusCode, text:''}); } }); });
    req.on('error',()=>resolve({status:0,text:''}));
    req.setTimeout(20000,()=>{ req.destroy(); resolve({status:0,text:''}); });
    req.write(payload); req.end();
  });
}

function callOpenAI(){
  return new Promise((resolve)=>{
    const payload = JSON.stringify({ model:OMODEL, messages:omsgs, temperature:0.6, max_tokens:500 });
    const req = https.request({ hostname:'api.openai.com', path:'/v1/chat/completions', method:'POST', headers:{'Content-Type':'application/json','Authorization':'Bearer '+OKEY,'Content-Length':Buffer.byteLength(payload)} }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>{ try{ const j=JSON.parse(d); const t=(((j.choices||[])[0]||{}).message||{}).content; resolve({status:res.statusCode, text:(t||'').trim()}); }catch(e){ resolve({status:res.statusCode,text:''}); } }); });
    req.on('error',()=>resolve({status:0,text:''}));
    req.setTimeout(20000,()=>{ req.destroy(); resolve({status:0,text:''}); });
    req.write(payload); req.end();
  });
}
async function callGemini(){
  const delays=[0, 600, 1400];
  let r;
  for (let i=0;i<delays.length;i++){ if (delays[i]) await sleep(delays[i] + Math.floor(Math.random()*300)); r = await callModelOnce(MODEL); if (r.text) return r; }
  r = await callModelOnce(MODEL_FALLBACK); if (r.text) return r;
  await sleep(1200); return await callModelOnce(MODEL_FALLBACK);
}

let g = await callOpenAI();
if (!g.text) g = await callGemini();
let reply = g.text || 'Oi! Estou aqui 😊 Me conta em que posso te ajudar — quer agendar uma avaliacao?';

const cards = [];
function fields(str){ return str.split('|').map(x=>x.trim()); }

const mAg = reply.match(/\[AGENDAMENTO\|([^\]]*)\]/i);
if (mAg) {
  const p = fields(mAg[1]);
  let c = '📅 NOVO AGENDAMENTO\n\n👤 ' + (p[0]||'Paciente') + ' (+' + number + ')\n🦷 ' + (p[1]||'-') + '\n📆 ' + (p[2]||'-') + '\n⏰ ' + (p[3]||'-');
  if (p[4] && p[4] !== '-') c += '\n📝 Obs: ' + p[4];
  c += '\n\nSalve na agenda da clinica.';
  cards.push(c);
  const ts = parseDT(p[2], p[3]);
  if (ts && ts > Date.now()) { s.appts = (s.appts||[]).filter(a=>a.number!==number); s.appts.push({ number, nome:p[0]||'Paciente', servico:p[1]||'-', dia:p[2]||'-', hora:p[3]||'-', ts, remind24:false, remind3:false }); }
  reply = reply.replace(/\[AGENDAMENTO\|[^\]]*\]/i,'').trim();
}

const mRe = reply.match(/\[REAGENDAMENTO\|([^\]]*)\]/i);
if (mRe) {
  const p = fields(mRe[1]);
  let c = '🔄 REAGENDAMENTO\n\n👤 ' + (p[0]||'Paciente') + ' (+' + number + ')\n🦷 ' + (p[1]||'-') + '\n📆 NOVO: ' + (p[2]||'-') + '\n⏰ ' + (p[3]||'-');
  if (p[4] && p[4] !== '-') c += '\n📝 Obs: ' + p[4];
  c += '\n\nAtualize na agenda da clinica.';
  cards.push(c);
  const ts = parseDT(p[2], p[3]);
  if (ts && ts > Date.now()) { s.appts = (s.appts||[]).filter(a=>a.number!==number); s.appts.push({ number, nome:p[0]||'Paciente', servico:p[1]||'-', dia:p[2]||'-', hora:p[3]||'-', ts, remind24:false, remind3:false }); }
  reply = reply.replace(/\[REAGENDAMENTO\|[^\]]*\]/i,'').trim();
}

const mCa = reply.match(/\[CANCELAMENTO\|([^\]]*)\]/i);
if (mCa) {
  const p = fields(mCa[1]);
  let c = '❌ CANCELAMENTO\n\n👤 ' + (p[0]||'Paciente') + ' (+' + number + ')';
  if (p[1] && p[1] !== '-') c += '\n📝 Motivo: ' + p[1];
  c += '\n\nLibere o horario na agenda da clinica.';
  cards.push(c);
  s.appts = (s.appts||[]).filter(a=>a.number!==number);
  reply = reply.replace(/\[CANCELAMENTO\|[^\]]*\]/i,'').trim();
}

let handoff = false;
if (reply.indexOf('[HANDOFF]') !== -1) { handoff = true; reply = reply.replace(/\[HANDOFF\]/g,'').trim(); }

reply = reply.replace(/\[[A-Z][A-Z_ ]{2,}[^\]]*\]/g,'').replace(/^\s*marcadores?\s*:?.*$/gim,'').replace(/\n{3,}/g,'\n\n').trim();
if (!reply) reply = 'Oi! Como posso te ajudar? 😊';
// anti-ban: delay humano + presenca 'digitando' na resposta ao paciente
const humanDelay = 400 + Math.floor(Math.random()*900);
let sendRes = await waSend(remoteJid, reply, humanDelay);
if (!sendRes || (sendRes.code!==200 && sendRes.code!==201)) { await sleep(700); sendRes = await waSend(remoteJid, reply, humanDelay); }

for (const c of cards) { await waSend(ALERT_GROUP, c); }

if (handoff) {
  s.paused[remoteJid] = Date.now();
  const alerta = '🔔 ATENDIMENTO HUMANO NECESSARIO\n\n👤 Paciente: ' + (pushName ? pushName + ' ' : '') + '(+' + number + ')\n💬 Mensagem: "' + text + '"\n\nBot pausado 6h neste contato. Alguem assume pelo WhatsApp.\nPra devolver ao bot: "voltar ' + number + '".';
  await waSend(ALERT_GROUP, alerta);
}

if (g.text) {
  hist.push({ role:'user', text });
  hist.push({ role:'model', text: reply });
  if (hist.length > 20) s.conv[remoteJid] = hist.slice(-20);
}

return [{ json: { ok:true, number, replied: reply, cards: cards.length, handoff, send: sendRes } }];

const KEY_EVO = 'f7aaaba7593506765800c7d58133007a';
const INSTANCE = 'secretaria-clinica';
const https = require('https');
const DAILY_CAP = 120;      // teto de envios ativos por dia (anti-ban)
const HORA_INI = 7;         // so envia lembrete entre 7h e 21h (Brasilia)
const HORA_FIM = 21;

function waSend(target, txt, delayMs){
  return new Promise((resolve)=>{
    const obj = { number: target, text: txt };
    // delay/presence NAO vai no body do Evolution (quebrava entrega)
    const payload = JSON.stringify(obj);
    const req = https.request({ hostname:\<REDACTED_PRIVATE_HOST>', path:'/message/sendText/'+INSTANCE, method:'POST', headers:{ 'Content-Type':'application/json', 'apikey':KEY_EVO, 'Content-Length':Buffer.byteLength(payload) } }, (res)=>{ let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve(res.statusCode)); });
    req.on('error',()=>resolve(0));
    req.setTimeout(30000,()=>{ req.destroy(); resolve(0); });
    req.write(payload); req.end();
  });
}

const s = $getWorkflowStaticData('global');
s.appts = s.appts || [];
const now = Date.now();

// janela de horario (anti-ban): fora disso, nao dispara envio ativo
const brHour = parseInt(new Date().toLocaleString('en-US',{ timeZone:'America/Sao_Paulo', hour:'2-digit', hour12:false }), 10);
if (brHour < HORA_INI || brHour >= HORA_FIM) {
  // ainda limpa vencidos, mas nao envia
  s.appts = s.appts.filter(a => a.ts >= now - 2*3600000);
  return [{ json:{ ok:true, skipped:'fora-horario', brHour } }];
}

// contador diario (anti-ban)
const dkey = new Date().toLocaleDateString('en-CA',{ timeZone:'America/Sao_Paulo' });
s.lembDay = s.lembDay || { date:dkey, count:0 };
if (s.lembDay.date !== dkey) s.lembDay = { date:dkey, count:0 };

const keep = []; const toSend = [];
for (const a of s.appts){
  if (a.ts < now - 2*3600000) continue;
  const rem = a.ts - now;
  if (!a.remind24 && rem <= 24*3600000 && rem > 3*3600000){
    a.remind24 = true;
    toSend.push({ number:a.number, msg:'Oi ' + a.nome + '! 😊 Passando pra lembrar da sua consulta na Clinica Sorriso em ' + a.dia + ' as ' + a.hora + '. Posso confirmar sua presenca? Responda SIM, ou me avise se precisar remarcar.' });
  } else if (!a.remind3 && rem <= 3*3600000 && rem > 0){
    a.remind3 = true;
    toSend.push({ number:a.number, msg:'Oi ' + a.nome + '! 🦷 Sua consulta e hoje as ' + a.hora + ' na Clinica Sorriso (Rua Exemplo, 123 - Sorocaba). Te esperamos!' });
  }
  keep.push(a);
}
s.appts = keep;

let sent = 0;
for (const x of toSend){
  if (s.lembDay.count >= DAILY_CAP) break; // respeita teto diario
  const delay = 1200 + Math.floor(Math.random()*1800);
  await waSend(x.number, x.msg, delay);
  s.lembDay.count++; sent++;
  await new Promise(r=>setTimeout(r, 3000 + Math.floor(Math.random()*4000))); // espaco humano entre envios
}
return [{ json:{ ok:true, checked:keep.length, sent, dailyCount:s.lembDay.count, brHour, at:new Date().toISOString() } }];
